extern "C" __global__ void __launch_bounds__(128, 1) scrc_k0_kernel(const float* __restrict__ p0, const float* __restrict__ p1, const float* __restrict__ p2, const float* __restrict__ p3, float* __restrict__ p4) {
  float products[256];
  float dots[16];
  float scores[16];
  float row_max[1];
  float weights[16];
  float row_sum[1];
  float probabilities[16];
  float output_products[16];
  float output_value[1];
  float scale = p3[0];
  for (int k = 0; k < 16; ++k) {
    for (int r = 0; r < 16; ++r) {
      products[((k * 16) + r)] = (p0[((((int)blockIdx.x) * 16) + r)] * p1[((k * 16) + r)]);
    }
  }
  #pragma unroll
  for (int i = 0; i < 16; ++i) {
    dots[i] = 0x0p+0f/*0.000000e+00*/;
    #pragma unroll
    for (int rv = 0; rv < 16; ++rv) {
      dots[i] = (dots[i] + products[((i * 16) + rv)]);
    }
  }
  for (int k_1 = 0; k_1 < 16; ++k_1) {
    float unmasked = (dots[k_1] * scale);
    float condval;
    if ((k_1 <= ((int)blockIdx.x))) {
      condval = unmasked;
    } else {
      condval = -0x1.dcd65p+29f/*-1.000000e+09*/;
    }
    scores[k_1] = condval;
  }
  row_max[0] = -CUDART_INF_F;
  #pragma unroll
  for (int rv_1 = 0; rv_1 < 16; ++rv_1) {
    row_max[0] = max(row_max[0], scores[rv_1]);
  }
  for (int k_2 = 0; k_2 < 16; ++k_2) {
    weights[k_2] = expf((scores[k_2] - row_max[0]));
  }
  row_sum[0] = 0x0p+0f/*0.000000e+00*/;
  #pragma unroll
  for (int rv_2 = 0; rv_2 < 16; ++rv_2) {
    row_sum[0] = (row_sum[0] + weights[rv_2]);
  }
  for (int k_3 = 0; k_3 < 16; ++k_3) {
    probabilities[k_3] = (weights[k_3] / row_sum[0]);
  }
  for (int d = 0; d < 16; ++d) {
    for (int k_4 = 0; k_4 < 16; ++k_4) {
      output_products[k_4] = (probabilities[k_4] * p2[((k_4 * 16) + d)]);
    }
    output_value[0] = 0x0p+0f/*0.000000e+00*/;
    #pragma unroll
    for (int rv_3 = 0; rv_3 < 16; ++rv_3) {
      output_value[0] = (output_value[0] + output_products[rv_3]);
    }
    p4[((((int)blockIdx.x) * 16) + d)] = output_value[0];
  }
}

